[Form]
public class AVAIncSimData extends FormRun
{
    AVAincSimPositionTmp         locAVAIncSimPosTmp;
    SalesQuotationTable          callerSalesQuotationTable;
    AVASpecialDiscQuotationTmp   locSpecialDiscQuotTmp;
    AVASpecialDiscQuotation      locSpecialDiscQuot;
    FormDataSource               callerSalesQuotTable_DS;



}

/// <summary>
/// designed from AVA
/// </summary>
public void init()
{
    if (!element.args().record())
    {
        throw error("@SYS22539");
    }

    callerSalesQuotationTable   = element.args().record();
    callerSalesQuotTable_DS = FormDataUtil::getFormDataSource(callerSalesQuotationTable);

    KCS_IncSimData::createFromParameters(callerSalesQuotationTable);

    AVASpecialDiscQuotation.setTempDB();

    super();
    element.initSpecialDiscQuotation();
    AVAincSimPositionTmp::fillData(locAVAIncSimPosTmp,callerSalesQuotationTable,locSpecialDiscQuotTmp);

    AVAincSimPositionTmp.linkPhysicalTableInstance(locAVAIncSimPosTmp);

    if (xUserInfo::checkUserRole('NDXSalesQuotationAgent'))
    {
        IncSimHeader.visible(false);
    }



}

public void initSpecialDiscQuotation()
{

    select firstonly locSpecialDiscQuot
        where locSpecialDiscQuot.QuotationId == callerSalesQuotationTable.QuotationId;

    locSpecialDiscQuotTmp.SpecialDiscountId1  = locSpecialDiscQuot.SpecialDiscountId1;
    locSpecialDiscQuotTmp.SpecialDiscountId2  = locSpecialDiscQuot.SpecialDiscountId2;
    locSpecialDiscQuotTmp.SpecialDiscountId3  = locSpecialDiscQuot.SpecialDiscountId3;
    locSpecialDiscQuotTmp.SpecialDiscountPct1 = locSpecialDiscQuot.SpecialDiscountPct1;
    locSpecialDiscQuotTmp.SpecialDiscountPct2 = locSpecialDiscQuot.SpecialDiscountPct2;
    locSpecialDiscQuotTmp.SpecialDiscountPct3 = locSpecialDiscQuot.SpecialDiscountPct3;
    locSpecialDiscQuotTmp.SpecialDiscountPct3 = locSpecialDiscQuot.SpecialDiscountPct3;
    locSpecialDiscQuotTmp.SpecialDiscountPct3 = locSpecialDiscQuot.SpecialDiscountPct3;
    locSpecialDiscQuotTmp.QuotationId         = locSpecialDiscQuot.QuotationId;

    locSpecialDiscQuotTmp.insert();



}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns></returns>
public boolean closed()
{
    boolean ret;

    ret = super();

    if (callerSalesQuotTable_DS)
    {
        callerSalesQuotTable_DS.research(true);
        callerSalesQuotTable_DS.positionToRecord(callerSalesQuotationTable);
    }

    return ret;
}

