/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_record">_record</param>
/// <param name = "_options">_options</param>
public void displayOption(Common _record, FormRowDisplayOption _options)
{

    AVAincSimPositionTmp        locIncSimPositionTmp = _record;

    super(_record, _options);

    if(locIncSimPositionTmp.IncColorLine == NoYes::Yes)
    {
        _options.backColor(65408); 
    }
}

