/// <summary>
/// designed from AVA
/// </summary>
public void clicked()
{
    super();
    KCS_IncSimData      incSimData;
    delete_from incSimData
        where incSimData.KCS_RefQuotationId == callerSalesQuotationTable.QuotationId;

    KCS_IncSimData::createFromParameters(callerSalesQuotationTable);
    AVAincSimPositionTmp::fillData(locAVAIncSimPosTmp,callerSalesQuotationTable,AVASpecialDiscQuotation);

    AVAincSimPositionTmp.linkPhysicalTableInstance(locAVAIncSimPosTmp);

    AVAincSimPositionTmp_DS.executeQuery();
    KCS_IncSimData_ds.executeQuery();

}

/// <summary>
/// designed from AVA
/// </summary>
public void clicked()
{
    super();

    delete_from locSpecialDiscQuotTmp;
    element.initSpecialDiscQuotation();

    AVAincSimPositionTmp::fillData(locAVAIncSimPosTmp,callerSalesQuotationTable,locSpecialDiscQuotTmp);

    AVAincSimPositionTmp.linkPhysicalTableInstance(locAVAIncSimPosTmp);
    AVASpecialDiscQuotation.linkPhysicalTableInstance(locSpecialDiscQuotTmp);

    AVAincSimPositionTmp_DS.executeQuery();
    AVASpecialDiscQuotation_DS.executeQuery();

}

/// <summary>
/// designed from AVA
/// </summary>
public void clicked()
{
    super();
    AVASpecialDiscQuotation         specialDiscQuotation = AVASpecialDiscQuotation::find(KCS_IncSimData.KCS_RefQuotationId);

    if (specialDiscQuotation.RecId)
    {
        specialDiscQuotation.SpecialDiscountId1 = AVASpecialDiscQuotation.SpecialDiscountId1;
        specialDiscQuotation.SpecialDiscountId2 = AVASpecialDiscQuotation.SpecialDiscountId2;
        specialDiscQuotation.SpecialDiscountId3 = AVASpecialDiscQuotation.SpecialDiscountId3;

        specialDiscQuotation.SpecialDiscountPct1 = AVASpecialDiscQuotation.SpecialDiscountPct1;
        specialDiscQuotation.SpecialDiscountPct2 = AVASpecialDiscQuotation.SpecialDiscountPct2;
        specialDiscQuotation.SpecialDiscountPct3 = AVASpecialDiscQuotation.SpecialDiscountPct3;
        ttsbegin;
        specialDiscQuotation.selectForUpdate(true);
        specialDiscQuotation.update();
        ttscommit;
    }

    SalesQuotationTable     salesQuotationTable;
    SalesQuotationLine      salesQuotationLine;

    salesQuotationTable = SalesQuotationTable::find(KCS_IncSimData.KCS_RefQuotationId);
    if (salesQuotationTable.RecId)
    {
        salesQuotationTable.KCS_MaxBonusAmount = KCS_IncSimData.KCS_MaxBonusAmount;
        salesQuotationTable.selectForUpdate(true);
        ttsbegin;
        salesQuotationTable.doUpdate();
        ttscommit;
    }

    while select  salesQuotationLine
            where salesQuotationLine.QuotationId == KCS_IncSimData.KCS_RefQuotationId
    {
        salesQuotationLine.KCS_LimitPrice           = salesQuotationLine.AVAcalcLimitPrice(AVASpecialDiscQuotation::find(KCS_IncSimData.KCS_RefQuotationId));
        salesquotationLine.KCS_LimitPricePuffer     = salesquotationLine.AVAcalcLimitPricePuffer();
        salesQuotationLine.selectForUpdate(true);
        ttsbegin;
        salesQuotationLine.doUpdate();
        ttscommit;
    }
    info("@NDX:NXASpecDiscAreTransfered");

}
